```tsx
import type { ReactElement } from "react";
import "./ButtonRow.css";

export interface ButtonRowProps {
  primaryLabel: string;
  onPrimary: () => void;
  primaryDisabled?: boolean;
  secondaryLabel: string;
  onSecondary: () => void;
  secondaryDisabled?: boolean;
  quietLabel: string;
  onQuiet: () => void;
  quietDisabled?: boolean;
}

export function ButtonRow({
  primaryLabel,
  onPrimary,
  primaryDisabled = false,
  secondaryLabel,
  onSecondary,
  secondaryDisabled = false,
  quietLabel,
  onQuiet,
  quietDisabled = false,
}: ButtonRowProps): ReactElement {
  return (
    <div className="button-row" role="group" aria-label="Actions">
      <button
        type="button"
        className="button-row__button button-row__button--primary"
        onClick={onPrimary}
        disabled={primaryDisabled}
      >
        {primaryLabel}
      </button>
      <button
        type="button"
        className="button-row__button button-row__button--secondary"
        onClick={onSecondary}
        disabled={secondaryDisabled}
      >
        {secondaryLabel}
      </button>
      <button
        type="button"
        className="button-row__button button-row__button--quiet"
        onClick={onQuiet}
        disabled={quietDisabled}
      >
        {quietLabel}
      </button>
    </div>
  );
}
```

```css
.button-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem 1rem;
}

.button-row__button {
  font: inherit;
  font-size: clamp(0.9rem, 0.85rem + 0.2vw, 1.05rem);
  font-weight: 600;
  line-height: 1.2;
  padding: 0.6em 1.3em;
  border-radius: 999px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition: background-color 150ms ease, color 150ms ease, border-color 150ms ease;
}

/* Primary: the main action, filled with the accent. */
.button-row__button--primary {
  background: var(--myelin);
  color: var(--slide);
  border-color: var(--myelin);
}

.button-row__button--primary:hover:not(:disabled) {
  background: var(--cresyl);
  border-color: var(--cresyl);
}

/* Secondary: outlined in the ink colour. */
.button-row__button--secondary {
  border-color: var(--ink);
}

.button-row__button--secondary:hover:not(:disabled) {
  background: var(--myelin-wash);
}

/* Quiet: text only, no fill and no border. */
.button-row__button--quiet {
  padding-left: 0.4em;
  padding-right: 0.4em;
  color: var(--ink);
}

.button-row__button--quiet:hover:not(:disabled) {
  color: var(--myelin);
  text-decoration: underline;
  text-underline-offset: 0.2em;
}

/* Keep the global focus outline; add a border cue on top of it. */
.button-row__button:focus-visible {
  border-color: var(--cresyl);
}

/* Disabled: muted token colours, no opacity, no hover. */
.button-row__button:disabled {
  cursor: not-allowed;
  color: var(--muted);
  background: transparent;
  border-color: var(--hair);
  text-decoration: none;
}

.button-row__button--quiet:disabled {
  border-color: transparent;
}

:root[data-motion="reduce"] .button-row__button {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .button-row__button {
    transition: none;
  }
}
